// P-code semantics check for the ADSP-218x module.  Reads test/emu/cases.txt (generated by
// test/emu/cases.py); for each case it writes the code at pm:0100, disassembles it (so DO UNTIL
// marks its loop end through the loop context, as auto-analysis does), sets registers and
// memory, emulates with Ghidra's EmulatorHelper until the PC reaches the end of the main code,
// and compares registers and memory with the hand-computed expectations.
// Memory locations are <space>:<hex word address> (pm words are 24 bits, dm/io words 16).
// Script args: <cases.txt> <outfile>
//@category Testing

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.PrintStream;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import ghidra.app.cmd.disassemble.DisassembleCommand;
import ghidra.app.emulator.EmulatorHelper;
import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.Address;
import ghidra.program.model.address.AddressSet;
import ghidra.program.model.address.AddressSpace;
import ghidra.program.model.lang.Register;
import ghidra.program.model.listing.ProgramContext;

public class ADSPEmuTest extends GhidraScript {

	private static class Case {
		String name;
		long[] code;
		int main = -1;
		Map<String, Long> set = new LinkedHashMap<>();
		Map<String, Long> expect = new LinkedHashMap<>();
	}

	private List<Case> load(String path) throws Exception {
		List<Case> cases = new ArrayList<>();
		Case c = null;
		try (BufferedReader r = new BufferedReader(new FileReader(path))) {
			String line;
			while ((line = r.readLine()) != null) {
				line = line.trim();
				if (line.isEmpty() || line.startsWith("#")) {
					continue;
				}
				String[] f = line.split("\\s+");
				switch (f[0]) {
					case "case":
						c = new Case();
						c.name = f[1];
						break;
					case "code":
						c.code = new long[f[1].length() / 6];
						for (int i = 0; i < c.code.length; i++) {
							c.code[i] = Long.parseLong(f[1].substring(6 * i, 6 * i + 6), 16);
						}
						break;
					case "main":
						c.main = Integer.decode(f[1]);
						break;
					case "set":
						c.set.put(f[1], Long.decode(f[2]));
						break;
					case "expect":
						c.expect.put(f[1], Long.decode(f[2]));
						break;
					case "end":
						cases.add(c);
						break;
					default:
						throw new IllegalArgumentException("bad line: " + line);
				}
			}
		}
		return cases;
	}

	private AddressSpace space(String loc) {
		return currentProgram.getAddressFactory().getAddressSpace(loc.split(":")[0]);
	}

	private Address word(AddressSpace sp, long w) {
		return sp.getTruncatedAddress(w, true);
	}

	private int unit(AddressSpace sp) {
		return sp.getAddressableUnitSize();
	}

	private byte[] bytes(long v, int n) {
		byte[] b = new byte[n];
		for (int i = 0; i < n; i++) {
			b[n - 1 - i] = (byte) (v >> (8 * i));	// big-endian words
		}
		return b;
	}

	private String runCase(Case c) throws Exception {
		AddressSpace pm = currentProgram.getAddressFactory().getAddressSpace("pm");
		Address start = word(pm, 0x100);
		Address last = word(pm, 0x100 + c.code.length + 8);
		AddressSet body = new AddressSet(start, last);
		clearListing(body);
		ProgramContext ctx = currentProgram.getProgramContext();
		Register creg = currentProgram.getLanguage().getContextBaseRegister();
		ctx.remove(start, last, creg);
		for (int i = 0; i < c.code.length + 8; i++) {
			setBytes(word(pm, 0x100 + i), bytes(i < c.code.length ? c.code[i] : 0, 3));
		}
		DisassembleCommand dis = new DisassembleCommand(start,
			new AddressSet(start, word(pm, 0x100 + c.code.length - 1)), true);
		dis.applyTo(currentProgram, monitor);
		long end = 0x100 + (c.main >= 0 ? c.main : c.code.length);

		EmulatorHelper emu = new EmulatorHelper(currentProgram);
		try {
			for (Map.Entry<String, Long> e : c.set.entrySet()) {
				String k = e.getKey();
				if (k.contains(":")) {
					AddressSpace sp = space(k);
					emu.writeMemory(word(sp, Long.parseLong(k.split(":")[1], 16)),
						bytes(e.getValue(), unit(sp)));
				}
				else {
					emu.writeRegister(k, e.getValue());
				}
			}
			emu.writeRegister(emu.getPCRegister(), 0x100);
			int steps = 0;
			while (emu.getExecutionAddress().getAddressableWordOffset() != end) {
				if (++steps > 2000) {
					return "did not reach the end (pc " + emu.getExecutionAddress() + ")";
				}
				if (!emu.step(monitor)) {
					return "emulation error at " + emu.getExecutionAddress() + ": " +
						emu.getLastError();
				}
			}
			StringBuilder bad = new StringBuilder();
			for (Map.Entry<String, Long> e : c.expect.entrySet()) {
				String k = e.getKey();
				long got;
				if (k.contains(":")) {
					AddressSpace sp = space(k);
					int n = unit(sp);
					byte[] b = emu.readMemory(word(sp, Long.parseLong(k.split(":")[1], 16)), n);
					got = 0;
					for (int i = 0; i < n; i++) {
						got = (got << 8) | (b[i] & 0xff);
					}
				}
				else {
					got = emu.readRegister(k).longValue();
				}
				if (got != e.getValue()) {
					bad.append(String.format(" %s=0x%x (expected 0x%x)", k, got, e.getValue()));
				}
			}
			return bad.length() == 0 ? null : bad.toString().trim();
		}
		finally {
			emu.dispose();
		}
	}

	@Override
	protected void run() throws Exception {
		String[] args = getScriptArgs();
		List<Case> cases = load(args[0]);
		int pass = 0, fail = 0;
		try (PrintStream out = new PrintStream(args[1])) {
			for (Case c : cases) {
				String err = runCase(c);
				if (err == null) {
					pass++;
					out.println("PASS " + c.name);
				}
				else {
					fail++;
					out.println("FAIL " + c.name + ": " + err);
				}
			}
			out.printf("emulation (%s): %d passed, %d failed%n", currentProgram.getLanguageID(),
				pass, fail);
		}
	}
}
